import{_ as i,o as e,c as s,a2 as t}from"./chunks/framework.NkFLIeLO.js";const k=JSON.parse('{"title":"宝塔面板安装与常用操作","description":"用一条命令装好宝塔面板，并记录数据库、Docker 与安全策略这三处最常用的操作。","frontmatter":{"title":"宝塔面板安装与常用操作","description":"用一条命令装好宝塔面板，并记录数据库、Docker 与安全策略这三处最常用的操作。","date":"2026-11-16T00:00:00.000Z","category":"工善利器","subCategory":"服务器运维","tags":["Linux","宝塔","运维"],"author":"闲生"},"headers":[],"relativePath":"posts/tools/server/baota.md","filePath":"posts/tools/server/baota.md"}'),p={name:"posts/tools/server/baota.md"};function n(h,a,r,l,o,d){return e(),s("div",null,[...a[0]||(a[0]=[t('<h1 id="宝塔面板安装与常用操作" tabindex="-1">宝塔面板安装与常用操作 <a class="header-anchor" href="#宝塔面板安装与常用操作" aria-label="Permalink to &quot;宝塔面板安装与常用操作&quot;">​</a></h1><p>宝塔是国内用得比较多的一款服务器面板，装完之后数据库、Docker、防火墙这些常用入口都能在网页里找到。这篇记录安装过程与日常最常碰到的三块功能。</p><h2 id="一、安装" tabindex="-1">一、安装 <a class="header-anchor" href="#一、安装" aria-label="Permalink to &quot;一、安装&quot;">​</a></h2><p>一条命令即可，执行过程中会提示确认：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">yum</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> install</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -y</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> wget</span><span style="--shiki-light:#999999;--shiki-dark:#666666;"> &amp;&amp;</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;"> wget</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -O</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> install.sh</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> https://download.bt.cn/install/install_6.0.sh</span><span style="--shiki-light:#999999;--shiki-dark:#666666;"> &amp;&amp;</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;"> sh</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> install.sh</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> ed8484bec</span></span></code></pre></div><p>安装完成后面板会打印访问地址、用户名和初始密码。</p><p><img src="https://pic.imgdb.cn/item/66175cd468eb935713edf4ca.png" alt="安装成功"></p><h2 id="二、登录与初始化" tabindex="-1">二、登录与初始化 <a class="header-anchor" href="#二、登录与初始化" aria-label="Permalink to &quot;二、登录与初始化&quot;">​</a></h2><p><img src="https://pic.imgdb.cn/item/66175cf268eb935713ee2486.png" alt="登录页面"></p><p>用安装页给出的账号密码登录。首次进入需要注册一个宝塔账号，按页面指引完成即可；之后面板会推荐安装环境套件（Nginx、MySQL、PHP 等），按自己的项目需要勾选，不需要的就跳过。</p><p><img src="https://pic.imgdb.cn/item/66175d0568eb935713ee4864.png" alt="选择环境"></p><h2 id="三、常用操作" tabindex="-1">三、常用操作 <a class="header-anchor" href="#三、常用操作" aria-label="Permalink to &quot;三、常用操作&quot;">​</a></h2><h3 id="数据库" tabindex="-1">数据库 <a class="header-anchor" href="#数据库" aria-label="Permalink to &quot;数据库&quot;">​</a></h3><p>在数据库页面先添加连接信息，再新建数据库。</p><p><img src="https://pic.imgdb.cn/item/66175d1768eb935713ee64cc.png" alt="数据库连接"></p><p><img src="https://pic.imgdb.cn/item/66175d2768eb935713ee81ab.png" alt="新建数据库"></p><p>创建完成后，列表里就会出现对应的库，可以直接管理表结构与账号权限。</p><p><img src="https://pic.imgdb.cn/item/66175d3d68eb935713eeb02a.png" alt="数据库列表"></p><h3 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;Docker&quot;">​</a></h3><p>Docker 页面可以拉取镜像、启动容器，也能从应用商店里选择已经配置好的服务，省去手写编排文件。</p><p><img src="https://pic.imgdb.cn/item/66175d4f68eb935713eed3a2.png" alt="Docker 管理"></p><h3 id="安全" tabindex="-1">安全 <a class="header-anchor" href="#安全" aria-label="Permalink to &quot;安全&quot;">​</a></h3><p>安全页面集中管理 Linux 的防火墙策略：开放端口、限制来源 IP 都在这里配置。云服务器还需要同步检查安全组规则，两处要一致，否则端口依然不通。</p><p><img src="https://pic.imgdb.cn/item/66175d6768eb935713eefdd0.png" alt="安全策略"></p><h2 id="四、小结" tabindex="-1">四、小结 <a class="header-anchor" href="#四、小结" aria-label="Permalink to &quot;四、小结&quot;">​</a></h2><p>宝塔把常见的运维入口收拢得比较整齐，适合快速把一台机器跑起来。记得及时改掉默认端口与初始密码，面板本身的安全同样重要。</p>',26)])])}const g=i(p,[["render",n]]);export{k as __pageData,g as default};
